import React, { useState } from 'react';
import { Menu, Search, ChevronDown, X, BookOpen } from 'lucide-react';

export default function Header() {
  const [isExploreOpen, setIsExploreOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const toggleExplore = () => {
    setIsExploreOpen(!isExploreOpen);
  };

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  const courses = {
    roles: ['Data Science', 'Web Development', 'Cloud Computing', 'Mobile Development', 'AI & Machine Learning']
  };

  const headerStyles = `
    <style>
      * {
        margin: 0;
        padding: 0;
        box-sizing: border-box;
      }

      .header {
        background: linear-gradient(to bottom, #ffffff, #f8f9ff);
        box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
        position: sticky;
        top: 0;
        z-index: 1000;
      }

      .header-container {
        max-width: 1400px;
        margin: 0 auto;
        padding: 0 24px;
        display: flex;
        align-items: center;
        justify-content: space-between;
        height: 72px;
        gap: 32px;
      }

      .header-left {
        display: flex;
        align-items: center;
        gap: 12px;
        min-width: 180px;
      }

      .menu-button {
        display: none;
        background: none;
        border: none;
        cursor: pointer;
        padding: 8px;
        border-radius: 8px;
        transition: background 0.2s;
      }

      .menu-button:hover {
        background: #f0f0f0;
      }

      .logo {
        font-size: 24px;
        font-weight: 700;
        background: linear-gradient(135deg, #4F46E5, #7C3AED);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        background-clip: text;
        display: flex;
        align-items: center;
        gap: 8px;
      }

      .nav-desktop {
        display: flex;
        gap: 32px;
        flex: 1;
        margin-top: 0;
      }

      .nav-link {
        color: #374151;
        text-decoration: none;
        font-weight: 500;
        font-size: 14px;
        padding: 8px 12px;
        border-radius: 6px;
        transition: all 0.2s;
        border: none;
        background: none;
        cursor: pointer;
        display: flex;
        align-items: center;
        gap: 6px;
      }

      .nav-link:hover {
        color: #4F46E5;
        background: rgba(79, 70, 229, 0.08);
      }

      .explore-container {
        position: relative;
      }

      .explore-dropdown {
        position: absolute;
        top: calc(100% + 8px);
        left: 0;
        background: white;
        border-radius: 12px;
        box-shadow: 0 10px 32px rgba(0, 0, 0, 0.12);
        min-width: 280px;
        padding: 16px;
        z-index: 1001;
      }

      .dropdown-section h3 {
        color: #111827;
        font-size: 13px;
        font-weight: 600;
        text-transform: uppercase;
        margin-bottom: 12px;
        letter-spacing: 0.5px;
      }

      .dropdown-section ul {
        list-style: none;
      }

      .dropdown-section li {
        margin-bottom: 8px;
      }

      .dropdown-section a {
        color: #6B7280;
        text-decoration: none;
        font-size: 14px;
        display: block;
        padding: 8px 12px;
        border-radius: 6px;
        transition: all 0.2s;
      }

      .dropdown-section a:hover {
        color: #4F46E5;
        background: #f3f4f6;
      }

      .header-right {
        display: flex;
        align-items: center;
        gap: 16px;
        min-width: fit-content;
      }

      .search-box {
        display: flex;
        align-items: center;
        gap: 12px;
        padding: 10px 16px;
        background: #f3f4f6;
        border-radius: 10px;
        max-width: 300px;
        transition: all 0.2s;
      }

      .search-box:focus-within {
        background: #e5e7eb;
        box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);
      }

      .search-box input {
        border: none;
        background: none;
        outline: none;
        font-size: 14px;
        color: #111827;
        width: 180px;
      }

      .search-box input::placeholder {
        color: #9CA3AF;
      }

      .search-box svg {
        color: #9CA3AF;
        flex-shrink: 0;
      }

      .sign-in-btn {
        padding: 10px 20px;
        border: none;
        border-radius: 10px;
        font-weight: 600;
        font-size: 14px;
        cursor: pointer;
        transition: all 0.2s;
        white-space: nowrap;
      }

      .sign-in-btn.secondary {
        background: transparent;
        color: #374151;
        border: 1.5px solid #d1d5db;
      }

      .sign-in-btn.secondary:hover {
        border-color: #4F46E5;
        color: #4F46E5;
      }

      .sign-in-btn.primary {
        background: linear-gradient(135deg, #4F46E5, #7C3AED);
        color: white;
        box-shadow: 0 4px 16px rgba(79, 70, 229, 0.3);
      }

      .sign-in-btn.primary:hover {
        transform: translateY(-2px);
        box-shadow: 0 6px 20px rgba(79, 70, 229, 0.4);
      }

      .mobile-menu {
        display: none;
        background: white;
        border-top: 1px solid #e5e7eb;
        padding: 16px 24px;
      }

      .mobile-nav-item {
        display: block;
        padding: 12px 0;
        color: #374151;
        text-decoration: none;
        font-weight: 500;
      }

      @media (max-width: 768px) {
        .menu-button {
          display: block;
        }

        .nav-desktop {
          display: none;
        }

        .header-container {
          height: 64px;
          gap: 16px;
          padding: 0 16px;
        }

        .header-right {
          flex: 1;
        }

        .search-box {
          max-width: none;
          flex: 1;
        }

        .search-box input {
          width: 100%;
        }
      }
    </style>
  `;

  return (
    <>
      {headerStyles}
      <header className="header">
        <div className="header-container">
          {/* Logo Section */}
          <div className="header-left">
            <button className="menu-button" onClick={toggleMobileMenu} aria-label="toggle menu">
              {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
            <h1 className="logo">
              <BookOpen size={28} style={{ color: '#4F46E5' }} />
              Learnix
            </h1>
          </div>

          {/* Navigation - Desktop */}
          <nav className="nav-desktop">
            <div className="explore-container">
              <button className="nav-link explore-btn" onClick={toggleExplore}>
                Explore <ChevronDown size={16} />
              </button>
              {isExploreOpen && (
                <div className="explore-dropdown">
                  <div className="dropdown-section">
                    <h3>Learning Paths</h3>
                    <ul>
                      {courses.roles.map((role, idx) => (
                        <li key={idx}><a href="#">{role}</a></li>
                      ))}
                    </ul>
                  </div>
                </div>
              )}
            </div>
            <a href="#" className="nav-link">Courses</a>
            <a href="#" className="nav-link">About</a>
          </nav>

          {/* Search & Auth Section */}
          <div className="header-right">
            <div className="search-box">
              <Search size={18} />
              <input type="text" placeholder="Search courses..." />
            </div>
            <button className="sign-in-btn secondary">Sign In</button>
            <button className="sign-in-btn primary">Log In</button>
          </div>
        </div>

        {/* Mobile Menu */}
        {isMobileMenuOpen && (
          <div className="mobile-menu">
            <div className="explore-container mobile">
              <button className="nav-link explore-btn" onClick={toggleExplore}>
                Explore <ChevronDown size={16} />
              </button>
              {isExploreOpen && (
                <div className="mobile-dropdown">
                  {courses.roles.map((role, idx) => (
                    <a key={idx} href="#" className="mobile-nav-item">{role}</a>
                  ))}
                </div>
              )}
            </div>
            <a href="#" className="mobile-nav-item">Courses</a>
            <a href="#" className="mobile-nav-item">About</a>
          </div>
        )}
      </header>
    </>
  );
}
